// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0); // plain EOA: the low-level payout call succeeds
        amount = bound(amount, 1, 1 ether);

        // actor deposits amount into c
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // actor withdraws; payout to an EOA succeeds in both versions
        vm.prank(actor);
        c.withdrawBalance();

        // General rule: a completed withdrawal always empties the contract's ether.
        // Correct C sends `amount` out; the mutant sends 0 wei and c retains the funds.
        assertTrue(address(c).balance == 0);
    }
}
